1	import { useState } from 'react';
2	import { useMutation, useQueryClient } from '@tanstack/react-query';
3	import { HttpError, postJson, putJson } from '../../api/http';
4	import { useSubmitOnce } from '../../query/useSubmitOnce';
5	import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
6	import { gradeOn, heldOn, usePeople, type Person } from '../people/usePeople';
7	import { periodOf, usePeriods } from '../periods/usePeriods';
8	import { rateOn, showDue, useRates } from '../rates/useRates';
9	import { useCap, useFloor, useLate } from '../settings/useSettings';
10	import { useSheetToday } from '../sheet/useSheet';
11	import { useSelectedClaims } from '../bulk/useSelectedClaims';
12	import {
13	  AMOUNT,
14	  CLAIM_NUMBER,
15	  claimDueCents,
16	  claimed,
17	  claimsKey,
18	  live,
19	  overdue,
20	  overdueFigures,
21	  personDueCents,
22	  capCents,
23	  excessCents,
24	  useClaims,
25	  type Claim,
26	} from './useClaims';
27	
28	const STATUS_REFUSED = "This claim's status cannot change that way (whoever opened a claim cannot settle it).";
29	const OVER_LIMIT = "A clerk cannot settle a claim whose due is over the sheet's clerk limit.";
30	const NOT_STEWARD = 'Only a steward can approve a pending claim, and never the user who opened it.';
31	const NOT_ALLOWED = "Your role may not do that: the sheet's permission matrix decides who opens, settles and voids claims.";
32	const CANNOT_VOID_SETTLED = 'Only a steward can void a SETTLED claim, and only within 7 days of its settlement (never one dated in a closed period).';
33	const NO_REASON = 'A rejection needs a reason.';
34	const NOT_STEWARD_MOVE = "Your role may not reassign a claim (by default only a steward can).";
35	const CANNOT_MOVE = 'Only a DRAFT, OPEN or PENDING claim can be reassigned to another person.';
36	const CANNOT_RESETTLE = 'Only a steward can re-settle a claim, and only a SETTLED one dated outside a closed period.';
37	const NO_TARGET = 'Choose another person to reassign this claim to.';
38	const CANNOT_DEFER = "Only an OPEN claim dated outside a closed period can be deferred, and only to a date after the sheet's today.";
39	const CANNOT_REDATE = "Only a steward can re-date a claim, only an OPEN or PENDING one, never in or into a closed period, nor to a date after its person's retirement.";
40	const DEFERRED = 'A deferred claim cannot be settled until the sheet\'s today reaches its deferred-until date.';
41	const NEEDS_PROOF = "A claim whose due is above the sheet's proof threshold cannot be settled or approved until it has a proof.";
42	const CANNOT_PROVE = 'A proof cannot be added to a SETTLED or VOID claim, nor to one dated in a closed period.';
43	const CANNOT_SPLIT = "Only an OPEN claim (not deferred, nor dated in a closed period) can be split, by a user whose role may open a claim.";
44	const BAD_SPLIT = "The amount split off must be more than 0.00 and less than the claim's amount, with up to two decimals.";
45	const NOT_DRAFT = 'Only a DRAFT claim can be edited: to change an open claim, void it and add a new one.';
46	
47	const ACTIONS = ['open', 'settle', 'approve', 'reject', 'void'] as const;
48	type Action = (typeof ACTIONS)[number];
49	const ACTION_LABELS: Record<Action, string> = { open: 'Open', settle: 'Settle', approve: 'Approve', reject: 'Reject', void: 'Void' };
50	
51	/**
52	 * A person's claims: what they have claimed in all and their due-total, the sum of their claims' rounded dues,
53	 * one form to add a claim or edit the one whose editor is open (only a DRAFT can be edited), and the claims, newest first, each
54	 * with its period (the one whose dates contain its date, if any), its due (fixed once it is settled, else bound by the last statement, else at the rate in force on the claim's date, plus its late charge, at least the sheet's floor; in the
55	 * due-total too), its status, who opened it, whether a statement binds it and the buttons to open, settle, approve, reject (with a reason) or void it (a SETTLED one only by a steward within 7 days of its settlement; its opener cannot settle
56	 * or approve it), and for a steward to re-settle a SETTLED one at today's figure. A clerk's settle over the clerk limit leaves the claim PENDING until a steward approves
57	 * or rejects it; while PENDING it shows its live figure, not the one a statement bound it to.
58	 * Only OPEN, PENDING and SETTLED claims count toward claimed and the due-total, and not the OPEN or
59	 * PENDING ones dated within one of the person's holds, unless a statement binds them.
60	 * A claim with a negative amount is a correction: it names, by number, a SETTLED claim of the person
61	 * that it corrects (refused otherwise), shows that number, and its due has no floor and no late charge.
62	 * Each claim shows its due-by (fixed when it was added, from the terms of its person's grade) and whether it is overdue (OPEN and
63	 * due by before the sheet's today); the person shows how many of the claims that count are overdue
64	 * and their dues added up.
65	 * A steward can reassign a DRAFT, OPEN or PENDING claim to another person on the sheet: it keeps its
66	 * number and date, is no longer bound by a statement, and is listed as its new person's newest claim.
67	 * A steward can re-date an OPEN or PENDING claim (not in or into a closed period, nor after its person's
68	 * retirement): its due-by and any figure a statement bound stay; its period follows the new date.
69	 * An OPEN claim can be deferred until a date after the sheet's today: until today reaches it, it shows
70	 * deferred yes and its deferred-until date, counts in no total, is not overdue and cannot be settled.
71	 * Each claim shows its proofs count, raised by one with its proof button (not on a SETTLED or VOID claim,
72	 * nor one dated in a closed period); one whose due is above the sheet's proof threshold on its date
73	 * cannot be settled or approved while it has none.
74	 * An OPEN claim can be split: an amount (more than 0.00, less than its amount) goes off it into a new
75	 * OPEN claim with the same date and note, the next number, opened by the user, which shows the
76	 * original's number as split-from; the original keeps the rest and is no longer bound by a statement.
77	 */
78	function PersonClaims({ user, sheet, person }: { user: string; sheet: string; person: Person }) {
79	  const queryClient = useQueryClient();
80	  const { data: all = [] } = useClaims(sheet);
81	  const claims = all.filter((c) => c.personId === person.id);
82	  // Their OPEN and PENDING claims dated within a hold count toward neither claimed nor the due-total,
83	  // unless a statement binds them.
84	  const liveClaims = live(claims, (_, date) => heldOn(person, date));
85	  const { data: everyone = [] } = usePeople(sheet);
86	  const others = everyone.filter((p) => p.id !== person.id);
87	  const { data: rates = [] } = useRates(sheet);
88	  const { data: periods = [] } = usePeriods(sheet);
89	  const today = useSheetToday(sheet);
90	  const pct = rateOn(rates, gradeOn(person, today), today);
91	  const floor = useFloor(sheet);
92	  const lateBy = useLate(sheet);
93	  const cap = useCap(sheet);
94	  // The sum of their figures; their due-total is at most the cap, the rest their excess.
95	  const dueSum = personDueCents(liveClaims, floor, pct, (d) => rateOn(rates, gradeOn(person, d), d), lateBy);
96	  const late = overdueFigures(liveClaims, lateBy, floor, (d) => rateOn(rates, gradeOn(person, d), d));
97	  const [editing, setEditing] = useState<number | null>(null);
98	  const [amount, setAmount] = useState('');
99	  const [date, setDate] = useState('');
100	  const [note, setNote] = useState('');
101	  const [corrects, setCorrects] = useState('');
102	  const [invalid, setInvalid] = useState(false);
103	  // The claim whose last status change or edit was refused: its row shows the error.
104	  const [refused, setRefused] = useState<{ id: number; message: string } | null>(null);
105	  // The claims ticked for a bulk action (the bulk-open panel acts on them).
106	  const [selected, setSelected] = useSelectedClaims();
107	  // The reason typed for rejecting each pending claim, by claim id.
108	  const [reasons, setReasons] = useState<Record<number, string>>({});
109	  // The date typed for deferring each claim, by claim id.
110	  const [deferTo, setDeferTo] = useState<Record<number, string>>({});
111	  // The new date typed for re-dating each claim, by claim id.
112	  const [redateTo, setRedateTo] = useState<Record<number, string>>({});
113	  // The person chosen to reassign each claim to, by claim id.
114	  const [moveTo, setMoveTo] = useState<Record<number, string>>({});
115	  // The amount typed for splitting each claim, by claim id.
116	  const [splitOff, setSplitOff] = useState<Record<number, string>>({});
117	  const base = `/api/sheets/${encodeURIComponent(sheet)}`;
118	
119	  const submitOnce = useSubmitOnce();
120	  const save = useMutation({
121	    mutationFn: (c: { id: number | null; amount: string; date: string; note: string; corrects: string }) => {
122	      const body = { amount: c.amount, date: c.date, note: c.note, corrects: c.corrects, user };
123	      return c.id === null
124	        ? postJson<Claim>(`${base}/people/${person.id}/claims`, body)
125	        : putJson<Claim>(`${base}/claims/${c.id}`, body);
126	    },
127	    onSuccess: async () => {
128	      close();
129	      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
130	    },
131	    // An edit of a claim no longer a DRAFT is refused on the claim itself; the editor stays open.
132	    onError: async (e, c) => {
133	      if (c.id !== null && e instanceof HttpError && e.status === 409 && e.body.includes('DRAFT')) {
134	        setRefused({ id: c.id, message: NOT_DRAFT });
135	        await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
136	      }
137	    },
138	  });
139	
140	  const changeStatus = useMutation({
141	    mutationFn: (c: { id: number; action: Action; reason?: string }) =>
142	      postJson<Claim>(`${base}/claims/${c.id}/status`, { action: c.action, user, reason: c.reason }),
143	    onMutate: () => setRefused(null),
144	    onSuccess: (_, c) => {
145	      if (c.action === 'reject') setReasons((r) => ({ ...r, [c.id]: '' }));
146	    },
147	    onError: (e, c) =>
148	      setRefused({
149	        id: c.id,
150	        message: !(e instanceof HttpError)
151	          ? STATUS_REFUSED
152	          : e.body.includes('void a settled')
153	            ? CANNOT_VOID_SETTLED
154	          : e.body.includes('proof threshold')
155	            ? NEEDS_PROOF
156	          : e.body.includes('clerk limit')
157	            ? OVER_LIMIT
158	            : e.body.includes('deferred')
159	              ? DEFERRED
160	            : e.body.includes('Your role')
161	              ? NOT_ALLOWED
162	            : e.body.includes('approve')
163	              ? NOT_STEWARD
164	              : e.body.includes('reason')
165	                ? NO_REASON
166	                : STATUS_REFUSED,
167	      }),
168	    onSettled: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
169	  });
170	
171	  // A steward re-settles a SETTLED claim at the figure it would have today as an unbound open claim.
172	  const resettle = useMutation({
173	    mutationFn: (c: { id: number }) => postJson<Claim>(`${base}/claims/${c.id}/resettle`, { user }),
174	    onMutate: () => setRefused(null),
175	    onError: (_, c) => setRefused({ id: c.id, message: CANNOT_RESETTLE }),
176	    onSettled: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
177	  });
178	
179	  // An OPEN claim is deferred until a date after the sheet's today.
180	  const defer = useMutation({
181	    mutationFn: (c: { id: number; until: string }) =>
182	      postJson<Claim>(`${base}/claims/${c.id}/defer`, { until: c.until, user }),
183	    onMutate: () => setRefused(null),
184	    onSuccess: (_, c) => setDeferTo((d) => ({ ...d, [c.id]: '' })),
185	    onError: (_, c) => setRefused({ id: c.id, message: CANNOT_DEFER }),
186	    onSettled: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
187	  });
188	
189	  // A steward re-dates an OPEN or PENDING claim: its due-by and any bound figure stay as they were.
190	  const redate = useMutation({
191	    mutationFn: (c: { id: number; date: string }) =>
192	      postJson<Claim>(`${base}/claims/${c.id}/redate`, { date: c.date, user }),
193	    onMutate: () => setRefused(null),
194	    onSuccess: (_, c) => setRedateTo((d) => ({ ...d, [c.id]: '' })),
195	    onError: (_, c) => setRefused({ id: c.id, message: CANNOT_REDATE }),
196	    onSettled: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
197	  });
198	
199	  // A proof raises the claim's proofs count by one.
200	  const addProof = useMutation({
201	    mutationFn: (c: { id: number }) => postJson<Claim>(`${base}/claims/${c.id}/proof`, { user }),
202	    onMutate: () => setRefused(null),
203	    onError: (_, c) => setRefused({ id: c.id, message: CANNOT_PROVE }),
204	    onSettled: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
205	  });
206	
207	  // An amount split off an OPEN claim into a new OPEN claim.
208	  const split = useMutation({
209	    mutationFn: (c: { id: number; amount: string }) =>
210	      postJson<Claim>(`${base}/claims/${c.id}/split`, { amount: c.amount, user }),
211	    onMutate: () => setRefused(null),
212	    onSuccess: (_, c) => setSplitOff((s) => ({ ...s, [c.id]: '' })),
213	    onError: (e, c) =>
214	      setRefused({
215	        id: c.id,
216	        message: e instanceof HttpError && (e.status === 400 || e.body.includes('less than')) ? BAD_SPLIT : CANNOT_SPLIT,
217	      }),
218	    onSettled: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
219	  });
220	
221	  const reassign = useMutation({
222	    mutationFn: (c: { id: number; toPersonId: number }) =>
223	      postJson<Claim>(`${base}/claims/${c.id}/reassign`, { toPersonId: c.toPersonId, user }),
224	    onMutate: () => setRefused(null),
225	    onSuccess: (_, c) => setMoveTo((m) => ({ ...m, [c.id]: '' })),
226	    onError: (e, c) =>
227	      setRefused({
228	        id: c.id,
229	        message: e instanceof HttpError && e.body.includes('role')
230	          ? NOT_STEWARD_MOVE
231	          : e instanceof HttpError && e.body.includes('retired')
232	            ? 'That person is retired before this claim\'s date.'
233	            : e instanceof HttpError && e.body.includes('closed')
234	              ? 'This claim is dated in a closed period.'
235	              : CANNOT_MOVE,
236	      }),
237	    onSettled: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
238	  });
239	
240	  // An error goes as soon as its form is changed or submitted again, or an editor is opened.
241	  const clearError = () => {
242	    save.reset();
243	    setInvalid(false);
244	    setRefused(null);
245	  };
246	  const close = () => {
247	    setEditing(null);
248	    setAmount('');
249	    setDate('');
250	    setNote('');
251	    setCorrects('');
252	  };
253	  const open = (c: Claim) => {
254	    clearError();
255	    // Only a DRAFT can be edited: to change an open claim, void it and add a new one.
256	    if (c.status !== 'DRAFT') {
257	      cancel();
258	      setRefused({ id: c.id, message: NOT_DRAFT });
259	      return;
260	    }
261	    setEditing(c.id);
262	    setAmount(c.amount);
263	    setDate(c.date);
264	    setNote(c.note);
265	    setCorrects(c.corrects === null ? '' : String(c.corrects));
266	  };
267	  const cancel = () => {
268	    clearError();
269	    close();
270	  };
271	
272	  return (
273	    <>
274	      <td data-testid="person-claimed">{claimed(liveClaims)}</td>
275	      <td data-testid="person-due-total">{showDue(capCents(dueSum, cap))}</td>
276	      <td data-testid="person-excess">{showDue(excessCents(dueSum, cap))}</td>
277	      <td data-testid="person-overdue-count">{late.count}</td>
278	      <td data-testid="person-overdue-total">{showDue(late.cents)}</td>
279	      <td>
280	        <form
281	          data-testid="claim-form"
282	          onSubmit={(e) => {
283	            e.preventDefault();
284	            // A negative amount is a correction: it must name the number of the claim it corrects.
285	            if (!AMOUNT.test(amount.trim()) || (amount.trim().startsWith('-') && !CLAIM_NUMBER.test(corrects.trim()))) {
286	              // Refused here, before anything is sent: the store is untouched.
287	              save.reset();
288	              setInvalid(true);
289	              return;
290	            }
291	            setInvalid(false);
292	            submitOnce(() => save.mutateAsync({ id: editing, amount: amount.trim(), date: date.trim(), note, corrects: corrects.trim() }));
293	          }}
294	        >
295	          <input
296	            data-testid="claim-form-amount"
297	            aria-label="Amount"
298	            placeholder="0.00"
299	            value={amount}
300	            onChange={(e) => {
301	              setAmount(e.target.value);
302	              clearError();
303	            }}
304	          />{' '}
305	          <input
306	            data-testid="claim-form-date"
307	            aria-label="Date"
308	            placeholder="yyyy-mm-dd"
309	            value={date}
310	            onChange={(e) => {
311	              setDate(e.target.value);
312	              clearError();
313	            }}
314	          />{' '}
315	          <input
316	            data-testid="claim-form-note"
317	            aria-label="Note"
318	            placeholder="note"
319	            value={note}
320	            onChange={(e) => {
321	              setNote(e.target.value);
322	              clearError();
323	            }}
324	          />{' '}
325	          <input
326	            data-testid="claim-form-corrects"
327	            aria-label="Corrects claim number"
328	            placeholder="corrects no."
329	            value={corrects}
330	            onChange={(e) => {
331	              setCorrects(e.target.value);
332	              clearError();
333	            }}
334	          />{' '}
335	          <button type="submit" data-testid="claim-form-submit" disabled={save.isPending}>
336	            {editing === null ? 'Add claim' : 'Save claim'}
337	          </button>
338	          {(invalid || (save.isError && refused === null)) && (
339	            <span data-testid="claim-form-error" role="alert">
340	              {' '}
341	              {invalid
342	                ? 'The amount must have up to two decimals; a negative amount must name the number of the settled claim it corrects.'
343	                : save.error instanceof HttpError && save.error.status === 409 && save.error.body.includes('retired')
344	                  ? `${person.name} is retired from ${person.retiredFrom}: a claim cannot be dated after it.`
345	                  : save.error instanceof HttpError && save.error.body.includes('correction')
346	                    ? `A correction must name a settled claim of ${person.name}.`
347	                  : 'Could not save this claim.'}
348	            </span>
349	          )}
350	        </form>
351	        <ul data-testid="claim-list">
352	          {claims.map((c) => (
353	            <li key={c.id} data-testid={`claim-row-${c.id}`}>
354	              <input
355	                type="checkbox"
356	                data-testid="claim-select"
357	                aria-label="Select claim"
358	                checked={selected.includes(c.id)}
359	                onChange={(e) =>
360	                  setSelected(e.target.checked ? [...selected, c.id] : selected.filter((id) => id !== c.id))
361	                }
362	              />{' '}
363	              <span data-testid="claim-amount">{c.amount}</span>{' '}
364	              <span data-testid="claim-date">{c.date}</span>{' '}
365	              <span data-testid="claim-period">{periodOf(periods, c.date)?.name ?? ''}</span>{' '}
366	              <span data-testid="claim-note">{c.note}</span>{' '}
367	              <span data-testid="claim-due">{showDue(claimDueCents(c, floor, rateOn(rates, gradeOn(person, c.date), c.date), lateBy))}</span>{' '}
368	              <span data-testid="claim-number">{c.number ?? ''}</span>{' '}
369	              <span data-testid="claim-corrects">{c.corrects ?? ''}</span>{' '}
370	              <span data-testid="claim-status">{c.status}</span>{' '}
371	              <span data-testid="claim-opened-by">{c.openedBy ?? ''}</span>{' '}
372	              <span data-testid="claim-stated">{c.stated ? 'yes' : 'no'}</span>{' '}
373	              <span data-testid="claim-due-by">{c.dueBy}</span>{' '}
374	              <span data-testid="claim-overdue">{overdue(c, today) ? 'yes' : 'no'}</span>{' '}
375	              <span data-testid="claim-deferred">{c.deferred ? 'yes' : 'no'}</span>{' '}
376	              <span data-testid="claim-deferred-until">{c.deferredUntil ?? ''}</span>{' '}
377	              <span data-testid="claim-proofs">{c.proofs}</span>{' '}
378	              <span data-testid="claim-split-from">{c.splitFrom ?? ''}</span>{' '}
379	              <button
380	                type="button"
381	                data-testid="claim-proof"
382	                disabled={addProof.isPending}
383	                onClick={() => addProof.mutate({ id: c.id })}
384	              >
385	                Add proof
386	              </button>{' '}
387	              {ACTIONS.map((action) => (
388	                <span key={action}>
389	                  {action === 'reject' && (
390	                    <>
391	                      <input
392	                        data-testid="claim-reject-reason"
393	                        aria-label="Reason for rejecting"
394	                        placeholder="reason"
395	                        value={reasons[c.id] ?? ''}
396	                        onChange={(e) => {
397	                          setReasons({ ...reasons, [c.id]: e.target.value });
398	                          if (refused?.id === c.id) setRefused(null);
399	                        }}
400	                      />{' '}
401	                    </>
402	                  )}
403	                  <button
404	                    type="button"
405	                    data-testid={`claim-${action}`}
406	                    disabled={changeStatus.isPending}
407	                    onClick={() => {
408	                      if (action === 'reject' && (reasons[c.id] ?? '').trim() === '') {
409	                        // Refused here, before anything is sent: the store is untouched.
410	                        setRefused({ id: c.id, message: NO_REASON });
411	                        return;
412	                      }
413	                      changeStatus.mutate({ id: c.id, action, reason: action === 'reject' ? (reasons[c.id] ?? '').trim() : undefined });
414	                    }}
415	                  >
416	                    {ACTION_LABELS[action]}
417	                  </button>{' '}
418	                </span>
419	              ))}
420	              <button
421	                type="button"
422	                data-testid="claim-resettle"
423	                disabled={resettle.isPending}
424	                onClick={() => resettle.mutate({ id: c.id })}
425	              >
426	                Re-settle
427	              </button>{' '}
428	              <input
429	                data-testid="claim-defer-date"
430	                aria-label="Defer until"
431	                placeholder="yyyy-mm-dd"
432	                value={deferTo[c.id] ?? ''}
433	                onChange={(e) => {
434	                  setDeferTo({ ...deferTo, [c.id]: e.target.value });
435	                  if (refused?.id === c.id) setRefused(null);
436	                }}
437	              />{' '}
438	              <button
439	                type="button"
440	                data-testid="claim-defer"
441	                disabled={defer.isPending}
442	                onClick={() => defer.mutate({ id: c.id, until: (deferTo[c.id] ?? '').trim() })}
443	              >
444	                Defer
445	              </button>{' '}
446	              <input
447	                data-testid="claim-date-new"
448	                aria-label="New date"
449	                placeholder="yyyy-mm-dd"
450	                value={redateTo[c.id] ?? ''}
451	                onChange={(e) => {
452	                  setRedateTo({ ...redateTo, [c.id]: e.target.value });
453	                  if (refused?.id === c.id) setRefused(null);
454	                }}
455	              />{' '}
456	              <button
457	                type="button"
458	                data-testid="claim-redate"
459	                disabled={redate.isPending}
460	                onClick={() => redate.mutate({ id: c.id, date: (redateTo[c.id] ?? '').trim() })}
461	              >
462	                Re-date
463	              </button>{' '}
464	              <input
465	                data-testid="claim-split-amount"
466	                aria-label="Amount to split off"
467	                placeholder="0.00"
468	                value={splitOff[c.id] ?? ''}
469	                onChange={(e) => {
470	                  setSplitOff({ ...splitOff, [c.id]: e.target.value });
471	                  if (refused?.id === c.id) setRefused(null);
472	                }}
473	              />{' '}
474	              <button
475	                type="button"
476	                data-testid="claim-split"
477	                disabled={split.isPending}
478	                onClick={() => {
479	                  const amount = (splitOff[c.id] ?? '').trim();
480	                  if (!/^\d+(\.\d{1,2})?$/.test(amount)) {
481	                    // Refused here, before anything is sent: the store is untouched.
482	                    setRefused({ id: c.id, message: BAD_SPLIT });
483	                    return;
484	                  }
485	                  split.mutate({ id: c.id, amount });
486	                }}
487	              >
488	                Split
489	              </button>{' '}
490	              <select
491	                data-testid="claim-reassign-to"
492	                aria-label="Reassign to"
493	                value={moveTo[c.id] ?? ''}
494	                onChange={(e) => {
495	                  setMoveTo({ ...moveTo, [c.id]: e.target.value });
496	                  if (refused?.id === c.id) setRefused(null);
497	                }}
498	              >
499	                <option value="">reassign to…</option>
500	                {others.map((p) => (
501	                  <option key={p.id} value={String(p.id)}>
502	                    {p.name}
503	                  </option>
504	                ))}
505	              </select>{' '}
506	              <button
507	                type="button"
508	                data-testid="claim-reassign"
509	                disabled={reassign.isPending}
510	                onClick={() => {
511	                  const to = moveTo[c.id] ?? '';
512	                  if (to === '') {
513	                    // Refused here, before anything is sent: the store is untouched.
514	                    setRefused({ id: c.id, message: NO_TARGET });
515	                    return;
516	                  }
517	                  reassign.mutate({ id: c.id, toPersonId: Number(to) });
518	                }}
519	              >
520	                Reassign
521	              </button>{' '}
522	              <button type="button" data-testid="claim-edit" onClick={() => open(c)}>
523	                Edit
524	              </button>
525	              {editing === c.id && (
526	                <>
527	                  {' '}
528	                  <button type="button" data-testid="claim-cancel" onClick={cancel}>
529	                    Cancel
530	                  </button>
531	                </>
532	              )}
533	              {refused?.id === c.id && (
534	                <span data-testid="claim-error" role="alert">
535	                  {' '}
536	                  {refused.message}
537	                </span>
538	              )}
539	              <ol data-testid="claim-log">
540	                {c.log.map((line, i) => (
541	                  <li key={i} data-testid="claim-log-line">
542	                    {line}
543	                  </li>
544	                ))}
545	              </ol>
546	            </li>
547	          ))}
548	        </ul>
549	      </td>
550	    </>
551	  );
552	}
553	
554	export const contributions = [
555	  PersonColumns.fill({
556	    order: 10,
557	    Component: () => (
558	      <>
559	        <th>Claimed</th>
560	        <th>Due</th>
561	        <th>Excess</th>
562	        <th>Overdue</th>
563	        <th>Overdue due</th>
