public class SaveClaimLock {
    public void save(@Val ClaimLock lock, @Val Claim claim, Claims claims) {
        claims.unlockOthers(claim.getSheetId(), claim.getPersonId(), lock.user(), claim.getId());
        claims.save(claim);
    }
}
EOF
